// Generated by build.rs from the production crates/bunwasm-runtime/src/js/inspect.js.
#include "inspect-factory.h"

void filename_error(const std::string& name, int32_t line) {
  JSAutoRealm realm(context, global->get());
  JS::RootedObject target(context, global->get());
  JS::RootedValue error(context);
  check(JS_GetProperty(context, target, "filenameError", &error), "read filename error");
  JS::RootedObject errorObject(context, &error.toObject());
  JS::RootedObject frame(context, JS::ExceptionStackOrNull(errorObject));
  check(frame != nullptr, "virtual script has saved frame");
  JS::RootedObject item(context, saved_frame_object(context, frame, JS::SavedFrameSelfHosted::Exclude));
  check(item != nullptr, "virtual saved frame decoded");
  JS::RootedValue file(context);
  check(JS_GetProperty(context, item, "file", &file), "read saved frame filename");
  std::string actual;
  check(to_utf8(file, &actual) && actual == name, "saved frame preserves exact source-map key");
  const bunsm::DiagnosticFilename diagnostic(name);
  Value label(bsm_string(diagnostic.c_str(), strlen(diagnostic.c_str())));
  install("filenameLabel", label.handle);
  JS::RootedValue lineNumber(context);
  check(JS_GetProperty(context, item, "line", &lineNumber), "read saved frame line");
  check(lineNumber.toNumber() == line, "saved frame keeps original line");
  Value stack(script("if (!filenameError.stack.includes(filenameLabel + ':')) throw new Error(filenameError.stack);"));
}

void filename_script(const std::string& name, int32_t line) {
  const char* body = "globalThis.filenameError = new Error('filename'); import('filename-child');";
  std::string source = line < 0
      ? std::string("(function __bunwasm_cjs__(exports, require, module, __filename, __dirname) {\n\n") + body + "\n})"
      : body;
  bsm_handle out = 0;
  check(bsm_eval_script(source.data(), source.size(), name.data(), name.size(), line, &out), "virtual script compiles");
  Value result(out);
  if (line < 0) {
    Value receiver(bsm_undefined());
    bsm_handle called = 0;
    check(bsm_call(result.handle, receiver.handle, nullptr, 0, &called), "virtual CommonJS executes");
    bsm_release(called);
  }
  jobs();
  check(lastReferrer == name, "script private preserves exact dynamic-import referrer");
  filename_error(name, line < 0 ? 1 : line);
}

void filename_module(const std::string& name) {
  constexpr const char source[] = "import 'filename-child'; export const identity = {}; export const again = () => import('filename-child'); export const error = new Error('module filename');";
  bsm_handle out = 0;
  check(bsm_eval_module(source, sizeof(source) - 1, name.data(), name.size(), &out), "virtual module compiles");
  Value evaluation(out);
  jobs();
  check(lastReferrer == name, "module private preserves static-import referrer");
  bsm_handle imported = 0;
  check(bsm_import(name.data(), name.size(), &imported), "virtual module imports by full ID");
  Value promise(imported);
  jobs();
  check(bsm_promise_state(promise.handle) == 1, "virtual module import fulfills");
  Value ns(bsm_promise_result(promise.handle));
  bsm_handle required = 0;
  check(bsm_require(name.data(), name.size(), &required), "virtual module requires by full ID");
  Value requirePromise(required);
  jobs();
  Value requiredNamespace(bsm_promise_result(requirePromise.handle));
  check(bsm_same_value(ns.handle, requiredNamespace.handle), "require and import preserve module identity");
  install("filenameNamespace", ns.handle);
  Value capture(script("globalThis.filenameError = filenameNamespace.error;"));
  filename_error(name, 1);
  Value dynamic(script("globalThis.filenameAgain = filenameNamespace.again();"));
  jobs();
  check(lastReferrer == name, "module dynamic import retains original referrer");
}

// SavedFrame source provenance (docs/bun-patches/spidermonkey-saved-frame-source-kind.md).
// "N" is a compiler name with NUL and percent, "S" is its encoded label, which a
// sourceURL can also spell literally, and "O" is an ordinary name.
const std::string provenanceNul("/literal\0%.ts", 13);
const std::string provenanceLiteral = "/literal%00%25.ts";
const std::string provenanceOrdinary = "/ordinary.ts";
const std::string provenanceUnicodeLabel = "/日本語%2500🦀.ts";
const std::string provenanceUnicodeName = "/日本語%00🦀.ts";
constexpr auto filenameKind = JS::SavedFrameSourceKind::Filename;
constexpr auto displayKind = JS::SavedFrameSourceKind::DisplayURL;
constexpr auto excludeSelfHosted = JS::SavedFrameSelfHosted::Exclude;
constexpr auto includeSelfHosted = JS::SavedFrameSelfHosted::Include;

std::string printable(const std::string& text) {
  std::string out;
  char escape[5];
  for (unsigned char c : text) {
    if (c >= 32 && c != 127) {
      out += static_cast<char>(c);
      continue;
    }
    snprintf(escape, sizeof escape, "\\x%02x", c);
    out += escape;
  }
  return out;
}

std::string string_bytes(JSString* string) {
  JS::RootedValue value(context, JS::StringValue(string));
  std::string bytes;
  check(to_utf8(value, &bytes), "provenance label bytes");
  return bytes;
}

struct FrameView {
  std::string raw;
  JS::SavedFrameSourceKind kind;
  std::string file;
  bool sameString;
};

// Reads one frame the way the production reader does, plus its raw label and kind.
FrameView read_frame(JS::HandleObject frame, JS::SavedFrameSelfHosted selfHosted = excludeSelfHosted) {
  JS::RootedString raw(context);
  check(JS::GetSavedFrameSource(context, nullptr, frame, &raw, selfHosted) == JS::SavedFrameResult::Ok, "provenance raw source");
  JS::SavedFrameSourceKind kind = displayKind;
  check(JS::GetSavedFrameSourceKind(context, nullptr, frame, &kind, selfHosted) == JS::SavedFrameResult::Ok, "provenance source kind");
  JS::RootedObject item(context, saved_frame_object(context, frame, selfHosted));
  check(item != nullptr, "provenance frame object");
  JS::RootedValue file(context);
  check(JS_GetProperty(context, item, "file", &file) && file.isString(), "provenance frame file");
  return {string_bytes(raw), kind, string_bytes(file.toString()), file.toString() == raw};
}

void expect_frame(const char* label, const FrameView& view, const std::string& raw, JS::SavedFrameSourceKind kind,
                  const std::string& file) {
  if (view.raw == raw && view.kind == kind && view.file == file) return;
  fprintf(stderr, "FAIL provenance %s: raw=%s kind=%d file=%s\n", label, printable(view.raw).c_str(),
          static_cast<int>(view.kind), printable(view.file).c_str());
  abort();
}

void run_named(const std::string& name, const std::string& source) {
  bsm_handle out = 0;
  check(bsm_eval_script(source.data(), source.size(), name.data(), name.size(), 1, &out), "provenance script runs");
  Value result(out);
}

// Callers root the result before anything can collect.
JSObject* global_error_stack(const char* property) {
  JS::RootedObject target(context, global->get());
  JS::RootedValue error(context);
  check(JS_GetProperty(context, target, property, &error) && error.isObject(), "provenance error");
  JS::RootedObject object(context, &error.toObject());
  JSObject* frame = JS::ExceptionStackOrNull(object);
  check(frame != nullptr, "provenance error has a saved frame");
  return frame;
}

void setup_provenance_formatter() {
  Value factory(script(inspectFactorySource, "inspect.js"));
  install("inspectFactory", factory.handle);
  Value setup(script(
      "globalThis.provenanceMaps = [];"
      "globalThis.provenanceFormatter = inspectFactory({ native: { engine: 'spidermonkey' },"
      "  mapPosition(file) { provenanceMaps.push(file); return file === '/literal%00%25.ts' ? [91, 7] : undefined; },"
      "  getSourceLine() {}, isProxy() { return false; } });",
      "provenance-formatter"));
  printf("provenance formatter uses production inspect.js fnv1a=%016llx\n", inspectFactoryFnv1a);
}

// The production formatter must look up the reader's file and map the S key to line 91.
void expect_formatted(const char* property, const std::string& file) {
  Value expected(bsm_string(file.data(), file.size()));
  install("provenanceExpected", expected.handle);
  const std::string suffix = file == provenanceLiteral ? "':91:7'" : "':'";
  const std::string code = std::string("(() => { provenanceMaps.length = 0;"
      " const text = provenanceFormatter.formatError(globalThis.") + property + ");"
      " if (provenanceMaps[0] !== provenanceExpected) return 'mapPosition keys ' + JSON.stringify(provenanceMaps);"
      " return text.includes(provenanceExpected + " + suffix + ") ? '' : text; })()";
  Value result(script(code.c_str(), "provenance-format"));
  size_t length = 0;
  const char* text = bsm_string_data(result.handle, &length);
  if (length == 0) return;
  fprintf(stderr, "FAIL provenance formatter %s: %s\n", property, printable(std::string(text, length)).c_str());
  abort();
}

struct ProvenanceRow {
  const char* label;
  std::string name;
  std::string source;
  std::string raw;
  JS::SavedFrameSourceKind kind;
  std::string file;
  bool sameString;
};

void provenance_row(const ProvenanceRow& row) {
  run_named(row.name, row.source);
  JSAutoRealm realm(context, global->get());
  JS::RootedObject frame(context, global_error_stack("filenameError"));
  const FrameView view = read_frame(frame);
  expect_frame(row.label, view, row.raw, row.kind, row.file);
  if (row.sameString && !view.sameString) {
    fprintf(stderr, "FAIL provenance %s: reader copied a label it must return unchanged\n", row.label);
    abort();
  }
  expect_formatted("filenameError", row.file);
}

void provenance_rows() {
  const std::string eval = " line 1 > eval";
  const std::string function = " line 1 > Function";
  const std::vector<ProvenanceRow> rows = {
      {"ordinary filename", provenanceOrdinary, "globalThis.filenameError = new Error('ordinary');",
       provenanceOrdinary, filenameKind, provenanceOrdinary, true},
      {"percent compiler filename", provenanceLiteral, "globalThis.filenameError = new Error('percent');",
       "/literal%2500%2525.ts", filenameKind, provenanceLiteral, false},
      {"NUL compiler filename", provenanceNul, "globalThis.filenameError = new Error('nul');",
       provenanceLiteral, filenameKind, provenanceNul, false},
      {"direct sourceURL", provenanceOrdinary,
       "globalThis.filenameError = new Error('sourceURL');\n//# sourceURL=/literal%00%25.ts",
       provenanceLiteral, displayKind, provenanceLiteral, true},
      {"eval sourceURL", provenanceOrdinary,
       "eval(\"globalThis.filenameError = new Error('eval sourceURL');\\n//# sourceURL=/literal%00%25.ts\");",
       provenanceLiteral, displayKind, provenanceLiteral, true},
      {"Function sourceURL", provenanceOrdinary,
       "globalThis.filenameError = Function(\"return new Error('Function sourceURL');\\n//# sourceURL=/literal%00%25.ts\")();",
       provenanceLiteral, displayKind, provenanceLiteral, true},
      {"Unicode sourceURL", provenanceOrdinary,
       "globalThis.filenameError = new Error('unicode');\n//# sourceURL=/日本語%2500🦀.ts",
       provenanceUnicodeLabel, displayKind, provenanceUnicodeLabel, true},
      {"eval Unicode sourceURL", provenanceOrdinary,
       "eval(\"globalThis.filenameError = new Error('eval unicode');\\n//# sourceURL=/日本語%2500🦀.ts\");",
       provenanceUnicodeLabel, displayKind, provenanceUnicodeLabel, true},
      {"Unicode compiler filename", provenanceUnicodeName, "globalThis.filenameError = new Error('unicode name');",
       provenanceUnicodeLabel, filenameKind, provenanceUnicodeName, false},
      {"inherited eval", provenanceNul, "eval(\"globalThis.filenameError = new Error('inherited eval');\");",
       provenanceLiteral + eval, filenameKind, provenanceNul + eval, false},
      {"inherited Function", provenanceNul,
       "globalThis.filenameError = Function(\"return new Error('inherited Function')\")();",
       provenanceLiteral + function, filenameKind, provenanceNul + function, false},
      {"Function inside eval", provenanceNul,
       "eval(\"globalThis.filenameError = Function('return new Error(1)')();\");",
       provenanceLiteral + eval + function, filenameKind, provenanceNul + eval + function, false},
  };
  for (const auto& row : rows) provenance_row(row);
}

// An eval without sourceURL inherits the outer compiler name, not the outer sourceURL.
void provenance_outer_source_url() {
  run_named(provenanceNul, "eval(\"globalThis.filenameError = new Error('inner');\");\n//# sourceURL=/ordinary.ts");
  JSAutoRealm realm(context, global->get());
  JS::RootedObject inner(context, global_error_stack("filenameError"));
  expect_frame("inner eval", read_frame(inner), provenanceLiteral + " line 1 > eval", filenameKind,
               provenanceNul + " line 1 > eval");
  JS::RootedObject outer(context);
  check(JS::GetSavedFrameParent(context, nullptr, inner, &outer, excludeSelfHosted) == JS::SavedFrameResult::Ok && outer,
        "outer frame");
  expect_frame("outer sourceURL", read_frame(outer), provenanceOrdinary, displayKind, provenanceOrdinary);
}

void same_position(JS::HandleObject first, JS::HandleObject second) {
  uint32_t firstLine = 0, secondLine = 0;
  JS::TaggedColumnNumberOneOrigin firstColumn, secondColumn;
  check(JS::GetSavedFrameLine(context, nullptr, first, &firstLine) == JS::SavedFrameResult::Ok &&
            JS::GetSavedFrameLine(context, nullptr, second, &secondLine) == JS::SavedFrameResult::Ok &&
            JS::GetSavedFrameColumn(context, nullptr, first, &firstColumn) == JS::SavedFrameResult::Ok &&
            JS::GetSavedFrameColumn(context, nullptr, second, &secondColumn) == JS::SavedFrameResult::Ok,
        "collision positions");
  check(firstLine == secondLine && firstColumn == secondColumn, "collision frames share a position");
}

// Equal labels at the same position from different branches stay distinct frames,
// whichever is captured first, while both Errors are alive.
void provenance_collision(bool filenameFirst) {
  const char* filenameProperty = filenameFirst ? "collisionA" : "collisionD";
  const char* displayProperty = filenameFirst ? "collisionB" : "collisionC";
  const std::string filenameCode = std::string("globalThis.") + filenameProperty + " = new Error('collision');";
  const std::string displayCode =
      std::string("globalThis.") + displayProperty + " = new Error('collision');\n//# sourceURL=/literal%00%25.ts";
  if (filenameFirst) run_named(provenanceNul, filenameCode);
  run_named(provenanceOrdinary, displayCode);
  if (!filenameFirst) run_named(provenanceNul, filenameCode);
  JSAutoRealm realm(context, global->get());
  JS::RootedObject filenameFrame(context, global_error_stack(filenameProperty));
  JS::RootedObject displayFrame(context, global_error_stack(displayProperty));
  same_position(filenameFrame, displayFrame);
  check(filenameFrame != displayFrame, "same label from different branches keeps distinct frames");
  expect_frame("collision filename", read_frame(filenameFrame), provenanceLiteral, filenameKind, provenanceNul);
  expect_frame("collision sourceURL", read_frame(displayFrame), provenanceLiteral, displayKind, provenanceLiteral);
  expect_formatted(filenameProperty, provenanceNul);
  expect_formatted(displayProperty, provenanceLiteral);
}

// Upstream still shares one frame for equal labels of the same kind.
void provenance_same_kind_sharing() {
  run_named(provenanceNul, "globalThis.sharedA = new Error('shared');");
  run_named(provenanceNul, "globalThis.sharedB = new Error('shared');");
  JSAutoRealm realm(context, global->get());
  JS::RootedObject first(context, global_error_stack("sharedA"));
  JS::RootedObject second(context, global_error_stack("sharedB"));
  check(first == second, "same-kind equal frames are still shared");
}

unsigned provenanceAdds = 0;
unsigned provenanceReleases = 0;
void provenance_private_add(const JS::Value& value) {
  if (!value.isString()) return;
  ++provenanceAdds;
}
void provenance_private_release(const JS::Value& value) {
  if (value.isString()) ++provenanceReleases;
}

// Script-private names die with their scripts; the kind lives in each retained frame.
void provenance_lifetime() {
  bsm_gc();
  bsm_gc();
  JS::SetScriptPrivateReferenceHooks(JS_GetRuntime(context), provenance_private_add, provenance_private_release);
  run_named(provenanceNul, "globalThis.retainedFilename = new Error('retained');");
  run_named(provenanceOrdinary, "globalThis.retainedDisplay = new Error('retained');\n//# sourceURL=/literal%00%25.ts");
  bsm_gc();
  bsm_gc();
  JS::SetScriptPrivateReferenceHooks(JS_GetRuntime(context), nullptr, nullptr);
  printf("provenance lifetime privateAdds=%u privateReleases=%u\n", provenanceAdds, provenanceReleases);
  check(provenanceAdds == 2 && provenanceReleases == 2, "both script privates released while their Errors remain");
  JSAutoRealm realm(context, global->get());
  JS::RootedObject filenameFrame(context, global_error_stack("retainedFilename"));
  JS::RootedObject displayFrame(context, global_error_stack("retainedDisplay"));
  expect_frame("retained filename", read_frame(filenameFrame), provenanceLiteral, filenameKind, provenanceNul);
  expect_frame("retained sourceURL", read_frame(displayFrame), provenanceLiteral, displayKind, provenanceLiteral);
  expect_formatted("retainedFilename", provenanceNul);
  expect_formatted("retainedDisplay", provenanceLiteral);
}

// Kind and source select the same frame under both self-hosted choices.
void provenance_self_hosted() {
  run_named(provenanceNul, "[1].map(function mapped() { globalThis.filenameError = new Error('map'); });");
  JSAutoRealm realm(context, global->get());
  JS::RootedObject frame(context, global_error_stack("filenameError"));
  expect_frame("map callback", read_frame(frame), provenanceLiteral, filenameKind, provenanceNul);
  JS::RootedObject selfHosted(context);
  check(JS::GetSavedFrameParent(context, nullptr, frame, &selfHosted, includeSelfHosted) == JS::SavedFrameResult::Ok &&
            selfHosted,
        "self-hosted parent");
  expect_frame("self-hosted map", read_frame(selfHosted, includeSelfHosted), "self-hosted", filenameKind, "self-hosted");
  expect_frame("Exclude from self-hosted", read_frame(selfHosted, excludeSelfHosted), provenanceLiteral, filenameKind,
               provenanceNul);
}

// An explicit async parent is copied through Lookup(SavedFrame&) and keeps its kind.
void provenance_async_parent() {
  run_named(provenanceNul, "globalThis.parentError = new Error('parent');");
  run_named(provenanceOrdinary,
            "globalThis.childCapture = function child() { globalThis.filenameError = new Error('child'); };\n"
            "//# sourceURL=/literal%00%25.ts");
  JSAutoRealm realm(context, global->get());
  JS::RootedObject parent(context, global_error_stack("parentError"));
  JS::RootedObject target(context, global->get());
  JS::RootedValue capture(context), ignored(context);
  check(JS_GetProperty(context, target, "childCapture", &capture), "async child function");
  {
    JS::AutoSetAsyncStackForNewCalls async(context, parent, "provenance");
    check(JS::Call(context, JS::UndefinedHandleValue, capture, JS::HandleValueArray::empty(), &ignored), "async child runs");
  }
  JS::RootedObject child(context, global_error_stack("filenameError"));
  expect_frame("async child", read_frame(child), provenanceLiteral, displayKind, provenanceLiteral);
  JS::RootedObject adopted(context);
  check(JS::GetSavedFrameAsyncParent(context, nullptr, child, &adopted, excludeSelfHosted) == JS::SavedFrameResult::Ok &&
            adopted,
        "async parent exists");
  JS::RootedString cause(context);
  check(JS::GetSavedFrameAsyncCause(context, nullptr, adopted, &cause, excludeSelfHosted) == JS::SavedFrameResult::Ok &&
            cause,
        "async parent carries its cause");
  check(adopted != parent, "async parent is a copied frame");
  expect_frame("async parent copy", read_frame(adopted), provenanceLiteral, filenameKind, provenanceNul);
}

void provenance_api_edges() {
  Value wasm(script("typeof WebAssembly", "provenance-wasm"));
  size_t length = 0;
  const char* type = bsm_string_data(wasm.handle, &length);
  check(std::string(type, length) == "undefined", "WebAssembly is not compiled; a Wasm frame row would be required");
  run_named(provenanceNul, "globalThis.filenameError = new Error('edges');");
  JSAutoRealm realm(context, global->get());
  JS::SavedFrameSourceKind kind = filenameKind;
  JS::RootedObject none(context);
  check(JS::GetSavedFrameSourceKind(context, nullptr, none, &kind) == JS::SavedFrameResult::AccessDenied &&
            kind == displayKind,
        "null frame reports raw");
  // Like every SavedFrame accessor, the kind accessor treats SavedFrame.prototype as a
  // precondition violation and crashes instead of reading slots it lacks. The reader only
  // receives frames from ExceptionStackOrNull and the parent accessors, never the prototype.
  JS::RootedObject frame(context, global_error_stack("filenameError"));
  JS::RootedObject prototype(context);
  check(JS_GetPrototype(context, frame, &prototype) && prototype, "SavedFrame prototype");
  check(js::IsSavedFrame(frame) && !js::IsSavedFrame(prototype), "SavedFrame.prototype is not a frame");
}

struct ProvenancePrincipals final : JSPrincipals {
  bool write(JSContext*, JSStructuredCloneWriter*) override { return false; }
  bool isSystemPrincipal() override { return false; }
  bool isAddonPrincipal() override { return false; }
};
ProvenancePrincipals framePrincipals;
ProvenancePrincipals deniedPrincipals;
JSPrincipals* lastSubsumed = nullptr;
unsigned principalsDestroyed = 0;
bool provenance_subsumes(JSPrincipals* first, JSPrincipals* second) {
  lastSubsumed = second;
  return first != &deniedPrincipals;
}
void provenance_destroy(JSPrincipals*) { ++principalsDestroyed; }

// Callers root the result before anything can collect.
JSObject* principal_frame(JS::HandleObject realmGlobal, bool muted, bool filename, bool function = false) {
  JSAutoRealm realm(context, realmGlobal);
  std::string source = "globalThis.principalError = new Error('principal');";
  if (function) source = "(function(){ " + source + " })();";
  if (!filename) source += "\n//# sourceURL=/literal%00%25.ts";
  JS::SourceText<mozilla::Utf8Unit> text;
  check(text.init(context, source.data(), source.size(), JS::SourceOwnership::Borrowed), "principal source");
  JS::CompileOptions options(context);
  const bunsm::DiagnosticFilename label(filename ? provenanceNul : provenanceOrdinary);
  options.setFileAndLine(label.c_str(), 1).setMutedErrors(muted);
  JS::RootedScript compiled(context, JS::Compile(context, options, text));
  check(compiled != nullptr, "principal script compiles");
  JS::RootedValue ignored(context), error(context);
  check(JS_ExecuteScript(context, compiled, &ignored), "principal script runs");
  check(JS_GetProperty(context, realmGlobal, "principalError", &error) && error.isObject(), "principal error");
  JS::RootedObject object(context, &error.toObject());
  return JS::ExceptionStackOrNull(object);
}

// Both flag bits share the principals word: the pointer, mutedErrors and kind stay exact.
void principal_combo(JS::HandleObject realmGlobal, bool muted, bool filename, bool function = false) {
  JS::RootedObject frame(context, principal_frame(realmGlobal, muted, filename, function));
  check(frame != nullptr, "principal frame");
  JSAutoRealm realm(context, realmGlobal);
  lastSubsumed = nullptr;
  JS::SavedFrameSourceKind kind = filename ? displayKind : filenameKind;
  check(JS::GetSavedFrameSourceKind(context, nullptr, frame, &kind) == JS::SavedFrameResult::Ok, "principal kind");
  check(kind == (filename ? filenameKind : displayKind), "principal frame keeps its kind");
  check(lastSubsumed == &framePrincipals, "masked principals pointer is exact");
  JS::SavedFrameKind frameKind = JS::SavedFrameKind::Unknown;
  check(JS::GetSavedFrameKind(context, nullptr, frame, &frameKind) == JS::SavedFrameResult::Ok &&
        frameKind == (function ? JS::SavedFrameKind::Function : JS::SavedFrameKind::Program), "principal frame kind");
  check(lastSubsumed == &framePrincipals, "kind accessor uses exact principal pointer");
  check(JS::GetSavedFrameKind(context, &deniedPrincipals, frame, &frameKind) == JS::SavedFrameResult::AccessDenied &&
        frameKind == JS::SavedFrameKind::Unknown, "denied kind has Unknown default");
  const FrameView view = read_frame(frame);
  check(view.file == (filename ? provenanceNul : provenanceLiteral), "principal frame reader file");
  JS::RootedValue thrown(context, JS::Int32Value(42));
  JS::ExceptionStack exception(context, thrown, frame);
  JS::ErrorReportBuilder report(context);
  check(report.init(context, exception, JS::ErrorReportBuilder::NoSideEffects), "principal error report");
  check(report.report()->isMuted == muted, "mutedErrors survives beside the kind bit");
  kind = filenameKind;
  check(JS::GetSavedFrameSourceKind(context, &deniedPrincipals, frame, &kind) == JS::SavedFrameResult::AccessDenied &&
            kind == displayKind,
        "denied frame reports raw");
  JS::RootedString source(context);
  check(JS::GetSavedFrameSource(context, &deniedPrincipals, frame, &source) == JS::SavedFrameResult::AccessDenied,
        "denied source matches denied kind");
}

void provenance_principals() {
  JS_InitDestroyPrincipalsCallback(context, provenance_destroy);
  const JSSecurityCallbacks* previous = JS_GetSecurityCallbacks(context);
  static const JSSecurityCallbacks callbacks = {nullptr, nullptr, provenance_subsumes};
  JS_SetSecurityCallbacks(context, &callbacks);
  JS_HoldPrincipals(&framePrincipals);
  JS::RealmOptions options;
  JS::RootedObject realmGlobal(context, JS_NewGlobalObject(context, &globalClass, &framePrincipals,
                                                           JS::DontFireOnNewGlobalHook, options));
  check(realmGlobal != nullptr, "principal global");
  {
    JSAutoRealm realm(context, realmGlobal);
    check(JS::InitRealmStandardClasses(context), "principal standard classes");
  }
  const int32_t before = framePrincipals.refcount;
  for (bool muted : {false, true}) {
    principal_combo(realmGlobal, muted, false);
    principal_combo(realmGlobal, muted, true);
    principal_combo(realmGlobal, muted, false, true);
    principal_combo(realmGlobal, muted, true, true);
  }
  const int32_t held = framePrincipals.refcount;
  {
    JSAutoRealm realm(context, realmGlobal);
    JS::RootedValue cleared(context);
    check(JS_SetProperty(context, realmGlobal, "principalError", cleared), "drop principal error");
  }
  bsm_gc();
  bsm_gc();
  printf("provenance principals refcount before=%d held=%d after=%d destroyed=%u\n", before, held,
         static_cast<int32_t>(framePrincipals.refcount), principalsDestroyed);
  check(held > before, "saved frames hold their principals");
  check(framePrincipals.refcount == before, "finalized frames drop the exact masked principals");
  check(principalsDestroyed == 0, "the control keeps its own principals reference");
  JS_SetSecurityCallbacks(context, previous);
}

void provenance_controls() {
  setup_provenance_formatter();
  provenance_rows();
  provenance_outer_source_url();
  provenance_collision(true);
  provenance_collision(false);
  provenance_same_kind_sharing();
  provenance_lifetime();
  provenance_self_hosted();
  provenance_async_parent();
  provenance_api_edges();
  provenance_principals();
  puts("SpiderMonkey SavedFrame source provenance controls passed");
}

void filename_controls() {
  sources["filename-child"] = "export const child = 42;";
  const std::vector<std::string> names = {
      "ordinary-filename.ts", "C:\\project\\file.ts", "日本語/🦀.ts", "%00",
      std::string("\0plugin-vue:export-helper", 25),
      std::string("/home/user/\0plugin-vue:export-helper", 36), std::string("\0a\0b\0", 5), std::string("日本語\0🦀%00\\.ts", 21)};
  JSObject* previous = nullptr;
  for (const auto& name : names) {
    filename_script(name, 17);
    filename_script(name, -1);
    filename_module(name);
    const auto found = modules.find(name);
    check(found != modules.end(), "full module cache key exists");
    check(found->second->record != previous, "different virtual IDs do not alias");
    previous = found->second->record;
  }
  provenance_controls();
  puts("SpiderMonkey virtual filename controls passed");
}
